package com.werewolf;
import com.fasterxml.jackson.databind.*;
import com.werewolf.community.CommunityService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties="jiujiu.media.directory=target/test-wall-media") @AutoConfigureMockMvc @ActiveProfiles("h2")
class CommunityIntegrationTest {
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired CommunityService service;
 record User(long id,String token){}
 JsonNode call(String method,String path,String token,Object body)throws Exception{var req=MockMvcRequestBuilders.request(org.springframework.http.HttpMethod.valueOf(method),path);if(token!=null)req.header("Authorization","Bearer "+token);if(body!=null)req.contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(body));return json.readTree(mvc.perform(req).andReturn().getResponse().getContentAsString(StandardCharsets.UTF_8));}
 JsonNode ok(String method,String path,User u,Object body)throws Exception{var r=call(method,path,u.token(),body);assertEquals(0,r.path("code").asInt(),r.toString());return r.path("data");}
 User user()throws Exception{String name="wp"+Long.toUnsignedString(System.nanoTime(),36);var r=call("POST","/api/auth/register",null,Map.of("username",name,"nickname",name,"password","demo1234"));assertEquals(0,r.path("code").asInt());return new User(r.path("data").path("user").path("id").asLong(),r.path("data").path("token").asText());}
 long post(User u,String key,String text)throws Exception{return ok("POST","/api/posts",u,Map.of("clientRequestId",key,"content",text)).path("id").asLong();}
 String image(User u,String purpose)throws Exception{var fixture=new org.springframework.core.io.ClassPathResource("fixtures/tiny.webp").getContentAsByteArray();var req=multipart("/api/media/images").file(new MockMultipartFile("file","wall.webp","image/webp",fixture)).param("purpose",purpose).header("Authorization","Bearer "+u.token());var result=json.readTree(mvc.perform(req).andReturn().getResponse().getContentAsString());assertEquals(0,result.path("code").asInt());return result.path("data").path("id").asText();}
 @Test void authorComesFromLoginAndOnlyAuthorCanDelete()throws Exception{var a=user();var b=user();var body=new HashMap<String,Object>();body.put("clientRequestId","author-key01");body.put("content","第一场狼人杀 🐺");body.put("authorId",b.id());var p=ok("POST","/api/posts",a,body);long id=p.path("id").asLong();assertEquals(a.id(),p.path("author").path("id").asLong());assertEquals("第一场狼人杀 🐺",ok("GET","/api/posts/"+id,b,null).path("content").asText());assertEquals(1001,call("GET","/api/posts",null,null).path("code").asInt());assertEquals(1002,call("DELETE","/api/posts/"+id,b.token(),null).path("code").asInt());ok("DELETE","/api/posts/"+id,a,null);ok("DELETE","/api/posts/"+id,a,null);assertEquals(1003,call("GET","/api/posts/"+id,b.token(),null).path("code").asInt());assertEquals(0,ok("GET","/api/posts?authorId="+a.id(),a,null).path("items").size());}
 @Test void likesAreIdempotentUnderConcurrentRetryAndCanBeRemoved()throws Exception{var a=user();var b=user();long id=post(a,"likes-key01","like me");var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{var f=pool.submit(()->service.like(b.id(),id,true));var g=pool.submit(()->service.like(b.id(),id,true));f.get();g.get();}finally{pool.shutdownNow();}assertEquals(1,ok("GET","/api/posts/"+id,a,null).path("likeCount").asInt());assertTrue(ok("GET","/api/posts/"+id,b,null).path("liked").asBoolean());ok("DELETE","/api/posts/"+id+"/like",b,null);ok("DELETE","/api/posts/"+id+"/like",b,null);assertEquals(0,ok("GET","/api/posts/"+id,a,null).path("likeCount").asInt());}
 @Test void commentsPersistRetryOnceAndRespectOwnershipAndPostDeletion()throws Exception{var a=user();var b=user();long id=post(a,"comments-p1","说两句");var body=Map.of("clientRequestId","comments-c1","content","好玩！");var c=ok("POST","/api/posts/"+id+"/comments",b,body);assertEquals(c.path("id"),ok("POST","/api/posts/"+id+"/comments",b,body).path("id"));assertEquals(1,ok("GET","/api/posts/"+id,a,null).path("commentCount").asInt());assertEquals("好玩！",ok("GET","/api/posts/"+id+"/comments",a,null).path("items").get(0).path("content").asText());assertEquals(1002,call("DELETE","/api/posts/"+id+"/comments/"+c.path("id").asLong(),a.token(),null).path("code").asInt());ok("DELETE","/api/posts/"+id+"/comments/"+c.path("id").asLong(),b,null);assertEquals(0,ok("GET","/api/posts/"+id,a,null).path("commentCount").asInt());ok("DELETE","/api/posts/"+id,a,null);assertEquals(1003,call("POST","/api/posts/"+id+"/comments",b.token(),Map.of("clientRequestId","comments-c2","content","gone")).path("code").asInt());assertEquals(1003,call("PUT","/api/posts/"+id+"/like",b.token(),null).path("code").asInt());}
 @Test void wallImageGrantRequiresPublicationAndIsRevokedOnDeletion()throws Exception{var a=user();var b=user();String media=image(a,"PRIVATE"),avatar=image(a,"AVATAR");assertEquals(1002,call("GET","/api/media/"+media+"/content",b.token(),null).path("code").asInt());assertEquals(1002,call("POST","/api/posts",b.token(),Map.of("clientRequestId","steal-image1","mediaIds",List.of(media))).path("code").asInt());assertEquals(1002,call("POST","/api/posts",a.token(),Map.of("clientRequestId","avatar-post1","mediaIds",List.of(avatar))).path("code").asInt());var p=ok("POST","/api/posts",a,Map.of("clientRequestId","image-post01","mediaIds",List.of(media)));long id=p.path("id").asLong();assertEquals(media,p.path("mediaIds").get(0).asText());mvc.perform(get("/api/media/"+media+"/content").header("Authorization","Bearer "+b.token())).andExpect(content().contentType(MediaType.IMAGE_PNG)).andExpect(header().string("Cache-Control","private, no-store"));assertEquals(1001,call("GET","/api/media/"+media+"/content",null,null).path("code").asInt());ok("DELETE","/api/posts/"+id,a,null);assertEquals(1002,call("GET","/api/media/"+media+"/content",b.token(),null).path("code").asInt());}
 @Test void cursorPaginationIsStableAndAuthorFilterWorks()throws Exception{var a=user();var b=user();for(int i=0;i<15;i++)post(a,"feed-key"+String.format("%04d",i),"post"+i);post(b,"other-user1","other");var first=ok("GET","/api/posts?authorId="+a.id()+"&limit=12",b,null);assertEquals(12,first.path("items").size());assertTrue(first.path("hasMore").asBoolean());long cursor=first.path("nextBeforeId").asLong();post(a,"newer-post1","new while paging");var second=ok("GET","/api/posts?authorId="+a.id()+"&beforeId="+cursor,b,null);assertEquals(3,second.path("items").size());assertTrue(second.path("items").get(0).path("id").asLong()<cursor);assertFalse(second.path("hasMore").asBoolean());}
 @Test void createRetryBoundariesAndInvalidContentAreRejected()throws Exception{var a=user();var body=Map.of("clientRequestId","retry-post1","content","😀".repeat(2000));var first=ok("POST","/api/posts",a,body);assertEquals(first.path("id"),ok("POST","/api/posts",a,body).path("id"));assertEquals(1000,call("POST","/api/posts",a.token(),Map.of("clientRequestId","retry-post1","content","changed")).path("code").asInt());for(var invalid:List.of(Map.of("clientRequestId","empty-post1","content","  "),Map.of("clientRequestId","long-post01","content","😀".repeat(2001)),Map.of("clientRequestId","bad","content","hi"))){assertEquals(1000,call("POST","/api/posts",a.token(),invalid).path("code").asInt());}assertEquals(1000,call("POST","/api/posts/"+first.path("id").asLong()+"/comments",a.token(),Map.of("clientRequestId","long-comment1","content","x".repeat(501))).path("code").asInt());assertEquals(1000,call("GET","/api/posts?limit=999",a.token(),null).path("code").asInt());}
}
